90	impl MigrationResults {
91	    pub(crate) fn add(&mut self, sourced_rule: &str, status: RuleMigrationResult) {
92	        let sourced = EslintRuleName::from_str(sourced_rule);
93	        match status {
94	            RuleMigrationResult::Migrated => {
95	                self.migrated.insert(sourced);
96	            }
97	            RuleMigrationResult::Inspired => {
98	                self.inspired.insert(sourced);
99	            }
100	            RuleMigrationResult::Nursery => {
101	                self.nursery.insert(sourced);
102	            }
103	            RuleMigrationResult::Unsupported => {
104	                let reason = unsupported_rule_reason(&sourced);
105	                self.unsupported.insert(sourced, reason);
106	            }
107	        }
108	    }
109	
110	    pub(crate) fn rule_count(&self) -> usize {
111	        self.migrated.len() + self.inspired.len() + self.nursery.len() + self.unsupported.len()
112	    }
113	}
