16	/// This modules includes implementations for loading and deserializing an eslint configuration.
17	///
18	/// See [super::eslint_eslint] for the data representation of an ESLint configuration.
19	///
20	/// Each ESLint plugin has its own module in which rule options are defined.
21	/// For example, the ESLint TypeScript plugin is defined in [super::eslint_typescript].
22	/// Note that we don't need to deserialise every existing rule option.
23	/// We only need to deserialise options that have equivalent biome options.
24	/// This greatly reduces the amount of work involved.
25	///
26	/// ESLint flat configuration filenames.
27	///
28	/// See https://eslint.org/docs/latest/use/configure/configuration-files-new
29	const FLAT_CONFIG_FILES: [&str; 3] = [
30	    // Prefixed with `./` to ensure that it is loadable via Node.js's `import()`
31	    "./eslint.config.js",
32	    "./eslint.config.mjs",
33	    "./eslint.config.cjs",
34	];
35	
36	/// List of ESLint **legacy** configuration filenames.
37	///
38	/// See https://eslint.org/docs/latest/use/configure/configuration-files
39	///
40	/// Order is important.
41	/// It translates the priority of the files.
42	/// For example, ESLint looks for `./.eslintrc.js` before looking for `./.eslintrc.json`.
43	const LEGACY_CONFIG_FILES: [&str; 6] = [
44	    // Prefixed with `./` to ensure that it is loadable via Node.js's `import()`
45	    "./.eslintrc.js",
46	    // Prefixed with `./` to ensure that it is loadable via Node.js's `import()`
47	    "./.eslintrc.cjs",
48	    ".eslintrc.yaml",
49	    ".eslintrc.yml",
50	    ".eslintrc.json",
51	    ".eslintrc",
52	];
53	
54	/// An ESLint config can be embedded in `package.json`
55	const PACKAGE_JSON: &str = "package.json";
56	
57	/// ESLint Ignore file. Use the same syntax as gitignore.
58	pub(crate) const IGNORE_FILE: &str = ".eslintignore";
59	
60	/// Returns the ESLint configuration file in the working directory with the highest priority.
61	///
62	/// This function respects the priority between ESLint configuration files.
63	/// For example, it looks for `./.eslintrc.js` before looking for `./.eslintrc.json`.
64	/// It first ries to load a flat configuration file.
65	///
66	/// Unlike ESLint, it doesn't look for a configuration file in parent directories
67	/// when no configuration file is found in the working directory.
68	///
69	/// Deserialization errors are reported using `console`.
70	/// Other errors (File Not found, unsupported config format, ...) are directly returned.
71	///
72	/// We extract the ESLint configuration from a JavaScript file, by invoking `node`.
73	///
74	/// The `extends` field is recursively resolved.
75	pub(crate) fn read_eslint_config(
76	    fs: &dyn FileSystem,
77	    console: &mut dyn Console,
78	) -> Result<Config, CliDiagnostic> {
79	    for config_path_str in FLAT_CONFIG_FILES {
80	        let path = Utf8Path::new(config_path_str);
81	        if fs.path_exists(path) {
82	            return load_flat_config_data(path, console).map(|data| Config {
83	                path: config_path_str,
84	                data: data.into(),
85	            });
86	        }
87	    }
88	    for config_path_str in LEGACY_CONFIG_FILES {
89	        let path = Utf8Path::new(config_path_str);
90	        if fs.path_exists(path) {
91	            return load_legacy_config_data(fs, path, console).map(|data| Config {
92	                path: config_path_str,
93	                data: data.into(),
94	            });
95	        }
96	    }
97	    // We don't report an error if ESLint config is not embedded in `PACKAGE_JSON`.
98	    if let Ok(data) = load_legacy_config_data(fs, Utf8Path::new(PACKAGE_JSON), console) {
99	        return Ok(Config {
100	            path: PACKAGE_JSON,
101	            data: data.into(),
102	        });
103	    }
104	    Err(CliDiagnostic::MigrateError(MigrationDiagnostic { reason: "The default ESLint configuration file `.eslintrc[.*]` was not found in the working directory.".to_string()}))
105	}
